table('figure_prevalence.csv',['split','test_family_contamination'],[{'split':'80/10/10','test_family_contamination':.2765669342},{'split':'90/5/5','test_family_contamination':.3030},{'split':'90/10','test_family_contamination':.2934}]);table('figure_capacity.csv',['model','parameters','tau'],[{'model':x['model'],'parameters':x['parameter_count'],'tau':x['effect']} for x in [by[k] for k in ['tcn_384','transformer_s','transformer_m','lmd_transformer_l']]]);table('figure_mitigation.csv',['protocol','cross_split_known_families'],[{'protocol':'file_split','cross_split_known_families':177},{'protocol':'exact_dedup','cross_split_known_families':161},{'protocol':'family_aware','cross_split_known_families':0}]);table('figure_external.csv',['dataset','tau','relative_improvement'],[{'dataset':'LMD','tau':l['effect'],'relative_improvement':l['relative_effect']},{'dataset':'PDMX reduced','tau':p['effect'],'relative_improvement':p['relative_effect']}])
